'use strict';
const app=document.getElementById('app');
const gradeMeta=[{id:'1-2',label:'1–2학년',title:'마음을 전하는 글자',desc:'글자를 만나고, 다정한 마음을 전해요.',method:'관찰 · 글자 놀이 · 마음 쪽지'},{id:'3-4',label:'3–4학년',title:'글자 발명 연구소',desc:'한글의 이야기를 알아보고 직접 만들어요.',method:'이야기 · 조합 실험 · 쉬운 말'},{id:'5-6',label:'5–6학년',title:'모두를 위한 문자, 한글',desc:'생각을 나누고, 누구나 읽는 글을 설계해요.',method:'자료 탐구 · 비교 · 안내문 설계'}];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function header(){return `<header class="site-header"><button class="brand" data-action="home" aria-label="한글날 첫 화면"><span class="brand-icon">ㅎ</span><span>한글날 배움 여행<small>10월 9일 · 우리 글자 이야기</small></span></button><nav class="header-links" aria-label="주 메뉴"><button data-action="guide">수업 안내</button><button data-action="worksheets">학습지 모음 ↗</button><span class="small-pill">초등 계기교육 · 교사용</span></nav></header>`}
function home(){document.body.classList.remove('presentation-mode','tablet-mode');app.innerHTML=header()+`<main id="main" class="home"><section class="home-hero"><div class="hero-copy"><div class="eyebrow">HANGEUL DAY <span class="date-pill">10월 9일</span></div><h1>마음을 잇는<br>위대한 글자, <em>한글.</em></h1><p class="hero-sub">세종의 마음에서 우리 교실의 이야기까지.<br>보고, 만들고, 함께 생각하는 한글날 수업을 시작해요.</p><div class="hero-meta"><span>학년별 3가지 여행</span><span>각 40분</span><span>활동 & 골든벨</span></div></div><figure class="hero-art"><img src="assets/hero-sejong.png" alt="붉은 곤룡포를 입은 세종을 상상하여 그린 교육용 삽화"><span class="floating-word" aria-hidden="true">우리의 한글</span><span class="floating-date"><strong>1446</strong>훈민정음 반포</span><figcaption>1446년 무렵 세종을 상상하여 표현한 그림</figcaption></figure></section><section aria-labelledby="choose-heading"><div class="section-heading"><h2 id="choose-heading">우리 반의 배움 여행을 골라요</h2><p>학년에 맞는 이야기와 활동이 준비되어 있어요</p></div><div class="grade-grid">${gradeMeta.map((g,i)=>`<button class="grade-card" data-grade="${g.id}"><div class="card-art"><img src="assets/${['classroom-note','writing-desk','school-sign'][i]}.png" alt="" loading="lazy"></div><div class="card-top"><span class="grade-tag">${g.label}</span><span class="level-number">0${i+1}</span></div><h3>${g.title}</h3><p>${g.desc}</p><div class="card-bottom"><span>${g.method}</span><span class="circle-arrow" aria-hidden="true">↗</span></div></button>`).join('')}</div></section><section class="teacher-strip"><span class="strip-symbol" aria-hidden="true">✳</span><div><h3>선생님은 이야기에만 집중하세요</h3><p>다음 버튼으로 수업 진행 · 큰 그림 슬라이드 · 질문과 정답 순차 공개</p></div><button class="btn ghost small" data-action="guide">수업 준비 살펴보기 ↗</button></section><footer class="page-footer"><span>오늘의 국경일 / 한글날 · 우리말과 우리 글자를 소중히</span><button data-action="sources">자료 출처와 그림 안내 ↗</button></footer></main>`;}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),4000)}
const data=window.HANGEUL_DATA;
const state={grade:'3-4',index:0,student:false,view:'home',notes:false,steps:0,letters:{c:2,v:0,t:0},assembled:false,timeline:{},classify:{},drafts:{},answers:{},reveal:{},quiz:0,quizStarted:false,quizFinished:false,reflection:false,showHint:false,checkChoice:null,checkReveal:false,introReveal:false,video:false,summary:0};
const CHO=['ㄱ','ㄲ','ㄴ','ㄷ','ㄸ','ㄹ','ㅁ','ㅂ','ㅃ','ㅅ','ㅆ','ㅇ','ㅈ','ㅉ','ㅊ','ㅋ','ㅌ','ㅍ','ㅎ'];
const JUNG=['ㅏ','ㅐ','ㅑ','ㅒ','ㅓ','ㅔ','ㅕ','ㅖ','ㅗ','ㅘ','ㅙ','ㅚ','ㅛ','ㅜ','ㅝ','ㅞ','ㅟ','ㅠ','ㅡ','ㅢ','ㅣ'];
const JONG=['','ㄱ','ㄲ','ㄳ','ㄴ','ㄵ','ㄶ','ㄷ','ㄹ','ㄺ','ㄻ','ㄼ','ㄽ','ㄾ','ㄿ','ㅀ','ㅁ','ㅂ','ㅄ','ㅅ','ㅆ','ㅇ','ㅈ','ㅊ','ㅋ','ㅌ','ㅍ','ㅎ'];
let clockId=null,seconds=480,clockEnd=0,previousFocus=null;
const getGrade=()=>data.grades[state.grade];
const storage={get(k){try{return localStorage.getItem('hangul:'+k)}catch{return null}},set(k,v){try{localStorage.setItem('hangul:'+k,v)}catch{}}};
const btn=(label,action,cls='light',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
function picture(file,alt,label,cls=''){return `<figure class="lesson-picture ${cls}"><img src="assets/${file}.png" alt="${esc(alt)}" decoding="async"><figcaption>${esc(label)}</figcaption></figure>`}
function modal(title,body,wide=false){closeModal(false);previousFocus=document.activeElement;document.getElementById('overlay').innerHTML=`<dialog class="modal ${wide?'wide':''}" aria-labelledby="modal-title"><div class="modal-heading"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="닫기">×</button></div>${body}</dialog>`;const d=document.querySelector('dialog');d.addEventListener('close',()=>{document.body.classList.remove('modal-open');previousFocus?.focus()});d.showModal();document.body.classList.add('modal-open');}
function closeModal(restore=true){const d=document.querySelector('dialog');if(d)d.close();document.getElementById('overlay').innerHTML='';document.body.classList.remove('modal-open');if(restore)previousFocus?.focus()}
function stopClock(){clearInterval(clockId);clockId=null;}
function startLesson(grade,index=0,student=false){if(!data.grades[grade])return;stopClock();state.grade=grade;state.student=student;state.view='lesson';state.index=Math.max(0,Math.min(9,Number(index)||0));state.quiz=0;state.quizStarted=false;state.quizFinished=false;state.answers={};state.reveal={};state.letters=grade==='3-4'?{c:18,v:0,t:4}:{c:2,v:0,t:0};state.classify={};state.timeline={};state.drafts={};enterSlide();closeModal();renderLesson();}
function enterSlide(){stopClock();state.presenterBeat=0;state.steps=0;state.checkChoice=null;state.checkReveal=false;state.summary=0;state.showHint=false;state.video=false;state.introReveal=false;state.reflection=false;seconds=getGrade().slides[state.index].minutes*60;if(!state.student)storage.set('progress:'+state.grade,String(state.index));const hash=state.student?`#student/${state.grade}/${state.index}`:`#lesson/${state.grade}/${state.index}`;history.replaceState(null,'',hash);}
function moveSlide(n){if(state.student&&window.moveTablet){window.moveTablet(n);return}if(!state.student&&window.movePresentation){window.movePresentation(n);return}if(state.index+n<0||state.index+n>9)return;state.index+=n;enterSlide();renderLesson();document.getElementById('slide-title')?.focus();}
function setupGrade(id){const g=data.grades[id],saved=Number(storage.get('progress:'+id));modal(`${g.label} · 수업 준비`,`<p class="modal-lead">${esc(g.title)}</p><ul class="clean-list">${g.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="prep-grid"><div><b>40분 · 10개 수업 단계</b><span>다음 → 질문 → 설명 → 활동 → 정답</span></div><div><b>준비물</b><span>필기도구 · 종이 또는 학생 기기</span></div></div><p class="note">PPT처럼 다음 버튼만 누르면 그림·질문·설명·정답이 순서대로 나옵니다. 학생은 손·말·종이로 참여해요.</p><div class="button-row">${btn('처음부터 수업 시작 →','start','',`data-grade-id="${id}"`)}${saved>0?btn(`${saved+1}번째 장면 이어보기`,'resume','light',`data-grade-id="${id}"`):''}${btn('학생용 학습지','pdf-student','ghost',`data-grade-id="${id}"`)}</div>`)}
function renderLesson(){if(state.student&&window.renderTablet){window.renderTablet();return}document.body.classList.remove('tablet-mode');if(!state.student&&window.renderPresentation){window.renderPresentation();return}document.body.classList.remove('presentation-mode');const g=getGrade(),s=g.slides[state.index];app.innerHTML=`<header class="lesson-top"><button class="brand" data-action="home"><span class="brand-icon">ㅎ</span><span>한글날 배움 여행</span></button><span class="lesson-context">${g.label} <span> / </span>${esc(g.title)}</span><div class="lesson-tools">${state.student?'<span class="tag">학생 활동</span>':btn('목차','contents','ghost small')}${btn('전체 화면','fullscreen','ghost small')}</div></header><main id="main" class="lesson-page"><div class="slide-heading"><div><span class="eyebrow">${String(state.index+1).padStart(2,'0')} / 10 <span class="stage-name">${['생각 열기','오늘의 미션','이야기 속으로','원리 탐험','영상과 관찰','참여 활동','잠깐 확인','배움 정리','마무리 평가','마음에 담기'][state.index]}</span></span><h1 id="slide-title" tabindex="-1">${esc(s.title)}</h1><p>${esc(s.body)}</p></div><span class="duration">${s.minutes}분</span></div><section class="slide-body scene-${s.kind}" aria-label="${esc(s.title)}">${renderScene(s.kind)}</section>${state.notes&&!state.student?`<aside class="teacher-notes"><strong>선생님의 발문과 도움말</strong><p>${esc(s.teacherNotes)}</p></aside>`:''}</main><footer class="lesson-controls"><div class="control-left">${!state.student?btn(state.notes?'교사 도움말 닫기':'교사 도움말','notes','ghost small'):btn('다른 학년','home','ghost small')}${!state.student?btn('QR 참여','qr','ghost small'):''}<button class="timer" data-action="timer" aria-label="활동 타이머 ${clockId?'일시정지':'시작'}"><span>${clockId?'Ⅱ':'▷'}</span> <span id="time-display">${timeText()}</span></button><button class="icon-btn reset-timer" data-action="timer-reset" aria-label="타이머 초기화">↺</button></div><div class="slide-dots" aria-label="수업 진행">${g.slides.map((x,i)=>`<button class="${i===state.index?'on':''}" data-jump="${i}" aria-label="${i+1}. ${esc(x.title)}" ${i===state.index?'aria-current="step"':''}></button>`).join('')}</div><div class="control-right">${btn('← 이전','prev','ghost',state.index===0?'disabled':'')}${state.index===9?btn('수업 마치기 ✓','home'):btn('다음 →','next')}</div></footer>`;}
function renderScene(kind){const g=getGrade(),low=state.grade==='1-2',high=state.grade==='5-6';switch(kind){
case'intro':if(high)return `<div class="split-scene"><div class="word-comparison"><span class="mini-label">같은 말, 다른 표기</span><div><strong>안녕</strong><span>한글로 적었어요</span></div><div><strong>annyeong</strong><span>로마자로 적었어요</span></div><p>소리 내어 읽고 무엇이 같은지, 무엇이 다른지 비교해요.</p></div><div class="thought-panel"><span class="mini-label">관찰 → 예상 → 설명</span><h2>말과 글자는<br>같은 뜻일까요?</h2><p>말의 뜻은 같지만 적는 문자는 달라요. 한국어와 한글을 구분할 단서를 찾아보세요.</p>${btn(state.introReveal?'설명 다시 가리기':'생각한 뒤 설명 보기','intro-toggle','orange')}${state.introReveal?'<div class="feedback success">한국어는 언어, 한글은 문자예요. 한국어를 로마자로 적을 수도 있어요.</div>':''}</div></div>`;return `<div class="split-scene"><div class="scene-visual sign-scene">${picture('school-sign','학교 복도의 빈 안내판을 바라보는 학생들','현대 한국 학교를 상상하여 표현한 그림')}<div class="sign-overlay ${state.introReveal?'visible':''}"><small>우리 학교 도서관</small><strong>책을 읽은 뒤<br>제자리에 꽂아 주세요.</strong></div></div><div class="thought-panel"><span class="mini-label">이미지 관찰</span><h2>${low?'안내판에 글자가 없다면?':high?'말은 알아듣는데,<br>글을 읽을 수 없다면?':'무슨 뜻인지<br>알 수 있을까요?'}</h2><p>그림 속 친구에게 필요한 정보를 생각해 보세요.</p>${btn(state.introReveal?'글자 다시 가리기':'안내문 열어 보기','intro-toggle','orange')}<p class="prompt">${state.introReveal?'글을 읽으니 무엇을 알게 되었나요?':'짝에게 예상한 내용을 이야기해 보세요.'}</p></div></div>`;
case'mission':return `<div class="split-scene mission"><div class="mission-list">${g.objectives.map((x,i)=>`<article><span>0${i+1}</span><h2>${esc(x)}</h2></article>`).join('')}<p class="prompt">오늘은 빨리 답하기보다, 왜 그런지 함께 생각해요.</p></div>${picture('classroom-note','친구에게 쪽지를 건네는 한국 초등학생들','현대 교실을 상상하여 표현한 그림')}</div>`;
case'story':return storyScene(low,high);
case'letters':return high?classification():letterLab(low);
case'video':return `<div class="split-scene"><div class="video-panel">${state.video?`<iframe title="${esc(data.video.title)}" src="${esc(data.video.embedUrl.replace('youtube.com','youtube-nocookie.com'))}" allow="accelerometer; encrypted-media; gyroscope; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`:`<div class="video-cover">${picture('writing-desk','붓과 한지, 벼루가 놓인 단정한 책상','전통 쓰기 도구를 표현한 교육용 정물')}<button class="play-button" data-action="video-play" aria-label="한글 영상 재생">▷</button></div>`}</div><div class="thought-panel"><span class="mini-label">보기 전 질문</span><h2>${low?'어떤 글자 모양을<br>발견했나요?':high?'한글을 만든 뜻을<br>어디서 찾았나요?':'새 글자는 사람들에게<br>어떤 도움이 될까요?'}</h2><p>${esc(data.video.title)}</p><div class="button-row"><a class="btn light" href="${esc(data.video.url)}" target="_blank" rel="noopener noreferrer">YouTube에서 열기 ↗</a>${btn('영상 대신 그림 이야기','video-alternative','ghost')}</div><details class="video-note"><summary>선생님, 수업 전 미리 확인해 주세요</summary><p>교육기관 안내에서 원본 링크를 확인했습니다. 현재 재생·길이·내용 전체와 임베드 허용은 확인되지 않았습니다. 적합한 약 2분 구간을 미리 골라 주세요. 영상이 열리지 않으면 그림 이야기로 같은 내용을 배울 수 있습니다.</p></details></div></div>`;
case'activity':return activityScene(low,high);
case'check':return checkScene(low,high);
case'summary':{const lines=low?['한글날은 10월 9일이에요.','낱자를 모아 글자를 만들어요.','한글로 생각과 마음을 전해요.']:high?['한국어는 언어, 한글은 문자예요.','1443년 창제, 1446년 반포를 구분해요.','읽는 사람을 생각하며 글을 고쳐요.']:['1443년 만들고, 1446년 널리 알렸어요.','처음 28자, 오늘날 기본 자모는 24자예요.','자음과 모음을 모아 뜻을 전해요.'];return `<div class="summary-grid">${lines.map((x,i)=>`<button class="summary-card ${i<state.summary?'revealed':''}" data-action="summary-reveal"><span>0${i+1}</span>${i<state.summary?`<h2>${x}</h2>`:'<h2>어떤 배움을 찾았나요?</h2><p>눌러서 핵심을 확인해요</p>'}</button>`).join('')}</div><p class="center prompt">먼저 기억나는 것을 말하고, 하나씩 열어 보세요.</p>`;}
case'assessment':return assessmentScene();
case'outro':return `<div class="split-scene outro"><div class="thought-panel"><span class="mini-label">오늘의 배움을 내일로</span><h2>한글로 전하는<br>나의 한마디.</h2><p>${esc(g.slides[9].body)}</p><label for="last-word">오늘 기억할 말</label><input id="last-word" data-draft="last" placeholder="나는 오늘…" maxlength="120" value="${esc(state.drafts.last||'')}"><div class="button-row">${btn('마음에 담기','finish','orange')}${btn('학습지 받기','worksheets','ghost')}</div>${state.reflection?'<div class="feedback success" role="status">오늘의 한글 여행을 잘 마쳤어요. 떠올린 말을 한 사람에게 전해 보세요.</div>':''}</div>${picture('library-together','도서관에서 함께 읽고 설명하는 한국 초등학생들','현대 학교 도서관을 상상하여 표현한 그림')}</div>`;
default:return'';}}
function storyScene(low,high){const scenes=[{file:'writing-desk',alt:'뜻을 적는 도구인 붓과 한지',label:'전통 쓰기 도구를 표현한 교육용 상징 그림',title:'말로 나눈 생각을 글로도 전하고 싶었어요.',body:'우리말은 있었지만, 한자를 배우고 뜻을 적는 데 어려움을 겪는 사람이 많았어요.'},{file:'hero-sejong',alt:'새 문자를 생각하는 세종의 상상 초상',label:'세종을 상상한 교육용 삽화 · 1443년 창제 현장 아님',title:'누구나 쉽게 배우고 쓸 수 있도록.',body:'세종은 백성이 자기 뜻을 쉽게 펴도록 새로운 글자를 만들었어요.'},{file:'writing-desk',alt:'붓과 한지, 옆으로 제본한 책을 표현한 정물',label:'실물 사료가 아닌 교육용 정물',title:low?'한글을 널리 알린 뜻을 기억해요.':'1443년 창제 → 1446년 반포',body:low?'10월 9일 한글날에는 한글의 소중함을 기억해요.':'창제는 새로 만든 것, 반포는 널리 알린 것이에요. 처음 이름은 훈민정음이에요.'}];const scene=scenes[state.steps];return `<div class="story-scene">${picture(scene.file,scene.alt,scene.label)}<div class="story-caption"><span class="mini-label">이야기 ${state.steps+1} / 3</span><h2>${scene.title}</h2><p>${scene.body}</p>${high&&state.steps===1?'<div class="source-evidence"><strong>자료 읽기 · 쉽게 다시 쓴 설명</strong><p>세종은 글로 자기 뜻을 펴기 어려운 백성을 생각해 쉽게 배우고 쓸 새 글자를 만들었습니다.</p><a href="https://www.hangeul.go.kr/exhi/dailyExhibition.do?curr_menu_cd=0102010000" target="_blank" rel="noopener">국립한글박물관 상설 전시 설명을 재서술 ↗</a><small>이 자료로 알 수 있는 창제 목적을 한 가지 말해 보세요.</small></div>':''}<div class="button-row">${btn('← 앞 장면','story-prev','ghost',state.steps===0?'disabled':'')}${btn(state.steps===2?'처음 이야기로 ↺':'다음 이야기 →','story-next','')}</div></div></div>${!low?`<div class="timeline"><button data-action="year" data-year="1443"><strong>1443</strong><span>${state.timeline['1443']?'창제 · 새 글자를 만듦':'무슨 일이 있었을까요?'}</span></button><span class="timeline-arrow">→</span><button data-action="year" data-year="1446"><strong>1446</strong><span>${state.timeline['1446']?'반포 · 널리 알림':'무슨 일이 있었을까요?'}</span></button><div><strong>10월 9일</strong><span>한글날</span></div></div>`:''}`}
function composed(){return String.fromCharCode(0xAC00+((state.letters.c*21)+state.letters.v)*28+state.letters.t)}
function letterLab(low){const cons=low?[0,2,6,9,11,18]:[0,2,3,5,6,7,9,11,12,18],vowels=low?[0,4,8,13,20]:[0,4,8,13,18,20],tails=[0,1,4,8,16,21];return `<div class="letter-lab"><div class="jamo-controls"><div class="jamo-row"><h3>${low?'첫 낱자':'자음 · 초성'}</h3><div>${cons.map(i=>`<button data-letter="c" data-value="${i}" class="jamo ${state.letters.c===i?'selected':''}" aria-pressed="${state.letters.c===i}">${CHO[i]}</button>`).join('')}</div></div><div class="jamo-row"><h3>${low?'만나는 낱자':'모음 · 중성'}</h3><div>${vowels.map(i=>`<button data-letter="v" data-value="${i}" class="jamo ${state.letters.v===i?'selected':''}" aria-pressed="${state.letters.v===i}">${JUNG[i]}</button>`).join('')}</div></div>${!low?`<div class="jamo-row"><h3>받침 · 종성</h3><div>${tails.map(i=>`<button data-letter="t" data-value="${i}" class="jamo ${state.letters.t===i?'selected':''}" aria-pressed="${state.letters.t===i}">${JONG[i]||'없음'}</button>`).join('')}</div></div>`:''}<p class="prompt">${low?'ㅏ를 ㅓ로 바꾸면 어떻게 될까요?':'한, 글, 나, 말… 어떤 글자를 만들 수 있나요?'}</p></div><div class="combination"><div class="letter-equation"><span>${CHO[state.letters.c]}</span><b>+</b><span>${JUNG[state.letters.v]}</span>${state.letters.t?`<b>+</b><span>${JONG[state.letters.t]}</span>`:''}</div><div class="syllable" aria-live="polite">${composed()}</div><p>낱자를 모아 한 글자로 써요</p>${btn('한 번 더 모아 보기','assemble','orange')}${!low?'<small>처음 훈민정음 28자 / 오늘날 기본 자모 24자<br>지금은 기본 자모 중 일부로 실험하고 있어요.</small>':''}</div></div>`}
const languageCases=[{text:'친구와 한국어로 대화해요. 여기서 ‘한국어’는 무엇인가요?',answer:'language',why:'한국어는 생각을 나누는 언어예요.'},{text:'ㄱ, ㄴ, ㅏ, ㅓ 같은 한글 낱자는 무엇인가요?',answer:'writing',why:'한글은 말을 적는 문자 체계예요.'},{text:'한글이 만들어지기 전에도 있었던 ‘우리말’은 무엇인가요?',answer:'language',why:'한국어는 한글 창제 이전에도 있었어요. 언어가 생긴 때와 문자가 만들어진 때는 달라요.'}];
function classification(){return `<div class="classify-grid">${languageCases.map((c,i)=>`<article class="classify-card"><span class="mini-label">사례 0${i+1}</span><h2>${c.text}</h2><div class="button-row"><button class="btn ${state.classify[i]==='language'?'':'ghost'}" data-classify="${i}" data-value="language" aria-pressed="${state.classify[i]==='language'}">언어 · 한국어</button><button class="btn ${state.classify[i]==='writing'?'':'ghost'}" data-classify="${i}" data-value="writing" aria-pressed="${state.classify[i]==='writing'}">문자 · 한글</button></div>${state.classify[i]?`<p class="feedback ${state.classify[i]===c.answer?'success':''}">${state.classify[i]===c.answer?'맞아요. ': '다시 생각해 보세요. '}${c.why}</p>`:''}</article>`).join('')}</div><p class="center prompt">언어는 생각을 나누는 말, 문자는 말을 적는 표기 체계예요.</p>`}
function activityScene(low,high){if(low)return `<div class="split-scene">${picture('classroom-note','친구에게 마음 쪽지를 건네는 아이들','현대 한국 교실을 상상하여 표현한 그림')}<div class="note-workshop"><span class="mini-label">마음 쪽지 공방</span><label for="recipient">누구에게 전할까요?</label><input id="recipient" data-draft="recipient" maxlength="30" value="${esc(state.drafts.recipient||'')}" placeholder="친구에게 / 가족에게"><div class="word-chips">${['도와줘서 고마워','우리 함께하자','괜찮아, 다시 해 보자'].map(x=>`<button data-message="${x}">${x}</button>`).join('')}</div><label for="message">전하고 싶은 말</label><textarea id="message" data-draft="message" rows="3" maxlength="240" placeholder="글로 쓰거나, 말을 골라 보세요.">${esc(state.drafts.message||'')}</textarea><div class="button-row">${btn('쪽지 완성하기','card-preview','orange')}${btn('처음부터','draft-reset','ghost')}</div><p class="note">이름 대신 ‘친구’라고 적어도 좋아요. 내용은 서버로 보내지 않아요.</p></div></div>`;return `<div class="redesign-workshop"><div class="original-notice"><span class="mini-label">바꾸기 전 안내문</span>${picture('school-sign','학교 안내판을 바라보는 학생들','현대 한국 학교를 상상하여 표현한 그림')}<blockquote>${high?'명일 09:00 체육관 집결,<br>실내화 지참.':'도서 열람 후 지정 장소에<br>반납하세요.'}</blockquote><p>${high?'언제·몇 시·어디·준비물 네 가지 정보를 지켜요.':'안내판 아래에는 ‘반납 칸’이 표시되어 있어요.'}</p></div><div class="note-workshop"><span class="mini-label">${high?'읽는 사람을 위한 설계':'우리 반 쉬운 말 연구소'}</span><label for="audience">누가 읽는 안내문인가요?</label><select id="audience" data-draft="audience">${['우리 반 친구','처음 온 1학년','학교에 처음 온 손님'].map(x=>`<option ${state.drafts.audience===x?'selected':''}>${x}</option>`).join('')}</select><label for="rewrite">쉬운 말로 고쳐 써 보세요</label><textarea id="rewrite" data-draft="rewrite" rows="3" maxlength="300" placeholder="${high?'내일 아침 9시에…':'책을 읽은 뒤…'}">${esc(state.drafts.rewrite||'')}</textarea><label for="reason">어떤 점이 더 이해하기 쉬워졌나요?</label><textarea id="reason" data-draft="reason" rows="2" maxlength="200" placeholder="나는 …을 …로 바꾸었어요.">${esc(state.drafts.reason||'')}</textarea><div class="button-row">${btn('새 안내문 살펴보기','notice-preview','orange')}${btn('도움말','activity-hint','ghost')}</div>${state.showHint?`<p class="feedback">${high?'“명일 → 내일”, “집결 → 모이기”, “지참 → 가져오기”. 내일·9시·체육관·실내화 정보를 모두 남겨 주세요.':'“열람 → 읽기”, “지정 장소 → 반납 칸”으로 구체적으로 고쳐 보세요. 어디에 어떻게 놓는지 알 수 있어야 해요.'}</p>`:''}</div></div>`}
function checkScene(low,high){const question=low?'한글날은 10월 9일이에요.':high?'한글이 만들어질 때 한국어도 처음 생겼어요.':'한글은 1446년에 처음 만들어졌어요.';const right=low?'O':'X',why=high?'한국어는 한글이 만들어지기 전에도 있었어요. 언어와 문자는 다른 개념이에요.':low?'10월 9일 한글날에는 한글의 소중함을 기억해요.':'1443년은 창제, 1446년은 반포예요. 만들고 널리 알린 때를 구분해요.';return `<div class="quick-check"><span class="mini-label">생각을 나누는 O / X</span><h2>${question}</h2><div class="ox-options">${['O','X'].map(x=>`<button class="${state.checkChoice===x?'selected':''}" data-check="${x}" aria-pressed="${state.checkChoice===x}">${x}</button>`).join('')}</div><p class="prompt">답과 함께 까닭도 말해 보세요.</p>${btn(state.checkReveal?'다시 생각하기':'정답과 이유 보기','check-reveal','orange')}${state.checkReveal?`<div class="feedback success" role="status"><strong>정답 ${right}</strong><p>${why}</p></div>`:''}</div>`}
function assessmentScene(){const g=getGrade();if(!state.quizStarted)return `<div class="assessment-start"><div class="assessment-art">${picture('hangul-garden','한지와 편지, 글쓰기 도구로 꾸민 배움의 정물','한글 배움을 상징한 창작 정물')}<span>도전, 한글 골든벨</span></div><div><span class="mini-label">탈락 없이, 모두 함께</span><h2>오늘 찾은 배움을<br>확인해 볼까요?</h2><p>${g.quiz.length}가지 질문 · 틀려도 다시 생각해요</p><div class="button-row">${btn('골든벨 시작 →','quiz-start','orange')}${btn('학습지로 확인하기','pdf-student','ghost',`data-grade-id="${state.grade}"`)}</div></div></div>`;if(state.quizFinished){const objective=g.quiz.filter(q=>q.type!=='open'),correct=objective.filter(q=>state.answers[q.id]===q.answerIndex).length;return `<div class="quiz-finish"><div class="completion-mark">ㅎ</div><h2>한글 탐험을 마쳤어요!</h2><p>${state.student?`선택형 ${objective.length}문항 중 ${correct}문항을 스스로 확인했어요.`:'모든 문제에 함께 참여한 우리 반을 칭찬해요.'}</p><p>말로 설명한 답은 선생님·친구와 이유를 나누어요.</p><div class="button-row">${btn('다시 도전하기','quiz-restart','light')}${btn('마지막 한마디 →','next')}</div></div>`}const q=g.quiz[state.quiz],selected=state.answers[q.id],revealed=state.reveal[q.id];return `<div class="quiz-panel"><div class="quiz-meta"><span>QUESTION ${String(state.quiz+1).padStart(2,'0')} / ${g.quiz.length}</span><span>${q.type==='open'?'내 생각 말하기':q.type==='ox'?'O / X':'생각하고 고르기'}</span></div><h2>${esc(q.question)}</h2>${q.id==='h12-q2'?'<div class="question-graphic">나 <span>→ ㅏ를 ㅓ로 →</span> ?</div>':q.id==='h34-q3'?'<div class="question-graphic">ㅎ + ㅏ + ㄴ = ?</div>':''}${q.type==='open'?`<label class="sr-only" for="open-answer">내 생각</label><textarea id="open-answer" data-answer="${q.id}" rows="3" maxlength="500" placeholder="말로 설명하거나 짧게 적어 보세요.">${esc(selected||'')}</textarea>`:`<div class="quiz-options">${q.options.map((x,i)=>`<button data-quiz-option="${i}" class="${selected===i?'selected':''} ${revealed&&i===q.answerIndex?'correct':''}" aria-pressed="${selected===i}"><span>${i+1}</span>${esc(x)}</button>`).join('')}</div>`}<div class="button-row">${btn('힌트','quiz-hint','ghost')}${btn(q.type==='open'?'예시와 기준 보기':'정답 공개','quiz-reveal','orange')}${btn(state.quiz===g.quiz.length-1?'도전 마치기 ✓':'다음 문제 →','quiz-next','',!revealed?'disabled':'')}</div>${state.showHint?`<p class="feedback">${esc(q.hint)}</p>`:''}${revealed?`<div class="feedback success" role="status"><strong>${q.type==='open'?'예시 답':`정답 ${q.answerIndex+1}. ${esc(q.options[q.answerIndex])}`}</strong>${q.type==='open'?`<p>${esc(q.answer)}</p>`:''}<p>${esc(q.explanation)}</p>${q.type==='open'?'<small>같은 뜻을 자신의 말로 설명해도 좋아요.</small>':''}</div>`:''}</div>`}
function guide(){modal('한글날, 이렇게 진행해요',`<p class="modal-lead">학년을 고르면 40분 수업이 시작됩니다.</p><ol class="guide-list"><li><b>수업 전</b><span>학습지와 필기도구를 준비하고 영상은 미리 확인해 주세요.</span></li><li><b>발표 중</b><span>다음 버튼·→·스페이스바·Page Down으로 질문과 정답을 순서대로 보여 주세요. 이전 버튼은 바로 앞 슬라이드로 돌아갑니다.</span></li><li><b>참여 활동</b><span>글자 조합·마음 쪽지·쉬운 안내문을 만들어요. 학생 기기가 없어도 교사 화면과 종이로 진행할 수 있어요.</span></li><li><b>마무리</b><span>골든벨 또는 학습지로 확인해요. 탈락 없이 모두 참여하고, 정답보다 이유를 함께 나눠요.</span></li></ol><div class="feedback">교사 도움말은 같은 화면에 펼쳐집니다. 학생에게 보여 주기 전에는 닫아 주세요. 타이머는 장면을 바꾸면 멈춥니다.</div><p class="note">학년별 마지막 위치만 이 브라우저에 저장합니다. 학생 이름·응답을 서버로 수집하지 않습니다. 작성한 문장은 현재 화면을 닫으면 사라질 수 있으니 필요한 내용은 종이에 옮겨 주세요.</p>`)}
function worksheets(){modal('한글날 학습지 모음',`<p class="modal-lead">학년별 학생용과 교사용을 따로 준비했어요.</p><div class="worksheet-grid">${gradeMeta.map(g=>`<article><span class="grade-tag">${g.label}</span><h3>${esc(g.title)}</h3><a class="btn" href="worksheets/hangul-${g.id}-student.pdf" target="_blank" rel="noopener">학생용 PDF ↗</a><a class="btn ghost" href="worksheets/hangul-${g.id}-teacher.pdf" target="_blank" rel="noopener">교사용 해설 ↗</a></article>`).join('')}</div><p class="note">학생용에는 정답이 들어 있지 않습니다. 인쇄할 때 A4·실제 크기를 선택해 주세요.</p>`,true)}
function sources(){modal('자료 출처와 그림 안내',`<p class="modal-lead">사실은 공식 자료로, 삽화는 자료의 성격을 밝혀서.</p><ul class="source-list">${data.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></li>`).join('')}</ul><div class="feedback"><strong>그림은 교육용 생성 삽화입니다.</strong><p>세종의 얼굴과 조선 생활 장면은 상상하여 표현한 재현이며 실물 사료가 아닙니다. 한국의 시대·문화 자료를 참고하고 중국풍 궁궐·복식·무협 연출을 제외했습니다. 붉은 곤룡포와 검은 익선관은 1444년부터 왕의 집무 복식이었다는 박물관 설명에 맞추었지만, 세종의 얼굴·용무늬·옷의 재단은 확인된 실물 복원이 아닙니다. 화면에 쓰인 그림과 짧은 영상은 교육용 상상 자료이며, 불확실한 세부는 역사적 증거로 사용하지 않습니다.</p></div><p class="note">YouTube 링크는 교육기관의 안내로 확인했으며, 현재 재생 여부와 전체 길이는 수업 전 확인이 필요합니다.</p>`,true)}
function contents(){modal('수업 목차',`<div class="contents-list">${getGrade().slides.map((s,i)=>`<button data-jump="${i}"><span>${String(i+1).padStart(2,'0')}</span><b>${esc(s.title)}</b><small>${s.minutes}분</small></button>`).join('')}</div>`)}
function qrModal(){if(window.openClassroomQr){window.openClassroomQr();return}const base=storage.get('share-base')||location.href.split('#')[0];modal('QR로 한글 활동 참여하기',`<p class="modal-lead">같은 학년의 참여 활동을 학생 기기에서 열어요.</p><label for="share-base">학생에게 열리는 수업 주소</label><input id="share-base" type="url" value="${esc(base)}" placeholder="https://…"><p class="note">교사 전용 비공개 주소와 localhost는 학생에게 열리지 않을 수 있어요. 학생 접근을 허용한 주소 또는 같은 교실 네트워크의 주소를 사용해 주세요.</p><div class="button-row">${btn('학생 활동 QR 만들기','qr-build','')}${btn('영상 QR 만들기','qr-video','ghost')}</div><div id="qr-result" class="qr-result"></div><p class="note">개인 활동용입니다. 학생 응답이 교사 화면으로 실시간 전송되지는 않습니다.</p>`)}
function makeQr(url,student){try{const u=new URL(url);if(!['https:','http:'].includes(u.protocol))throw Error('protocol');if(!window.qrcode){toast('QR 도구를 불러오지 못했어요. 아래 주소를 직접 열어 주세요.');return}const qr=window.qrcode(0,'M');qr.addData(u.href);qr.make();document.getElementById('qr-result').innerHTML=qr.createSvgTag({cellSize:5,margin:4,scalable:true})+`<a href="${esc(u.href)}" target="_blank" rel="noopener">${student?'학생 활동 열기':'원본 영상 열기'} ↗</a><p>${esc(u.href)}</p>${btn('주소 복사','copy-link','light',`data-url="${esc(u.href)}"`)}`}catch{toast('http:// 또는 https://로 시작하는 올바른 주소를 입력해 주세요.')}}
function timeText(){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}
function toggleTimer(){if(clockId){seconds=Math.max(0,Math.ceil((clockEnd-Date.now())/1000));stopClock();renderLesson();return}if(!seconds)seconds=getGrade().slides[state.index].minutes*60;clockEnd=Date.now()+seconds*1000;clockId=setInterval(()=>{seconds=Math.max(0,Math.ceil((clockEnd-Date.now())/1000));const display=document.getElementById('time-display');if(display)display.textContent=timeText();if(!seconds){stopClock();toast('활동 시간이 끝났어요. 생각을 나누어 볼까요?');renderLesson()}},250);renderLesson()}
async function handleAction(el){if(window.handleTabletAction?.(el))return;const a=el.dataset.action;
if(el.dataset.grade){setupGrade(el.dataset.grade);return}if(el.dataset.jump!==undefined){state.index=Number(el.dataset.jump);closeModal();enterSlide();renderLesson();return}if(el.dataset.letter){state.letters[el.dataset.letter]=Number(el.dataset.value);renderLesson();return}if(el.dataset.classify!==undefined){state.classify[el.dataset.classify]=el.dataset.value;renderLesson();return}if(el.dataset.message){state.drafts.message=el.dataset.message;renderLesson();return}if(el.dataset.check){state.checkChoice=el.dataset.check;state.checkReveal=false;renderLesson();return}if(el.dataset.quizOption!==undefined){state.answers[getGrade().quiz[state.quiz].id]=Number(el.dataset.quizOption);renderLesson();return}
switch(a){case'home':stopClock();closeModal();state.view='home';history.replaceState(null,'','#home');home();break;case'guide':guide();break;case'worksheets':worksheets();break;case'sources':sources();break;case'close':closeModal();break;case'start':startLesson(el.dataset.gradeId);break;case'resume':{const savedBeat=Number(storage.get('beat:'+el.dataset.gradeId))||0;startLesson(el.dataset.gradeId,storage.get('progress:'+el.dataset.gradeId));state.presenterBeat=savedBeat;renderLesson();break;}case'prev':moveSlide(-1);break;case'next':moveSlide(1);break;case'notes':if(!state.student&&window.renderPresentation){modal('교사 노트 · '+getGrade().slides[state.index].title,'<p class='+String.fromCharCode(34)+'modal-lead'+String.fromCharCode(34)+'>'+esc(getGrade().slides[state.index].teacherNotes)+'</p><p class='+String.fromCharCode(34)+'note'+String.fromCharCode(34)+'>노트는 현재 화면에 표시됩니다. 읽은 뒤 닫고 수업을 이어 주세요.</p>');}else{state.notes=!state.notes;renderLesson();}break;case'presenter-tools':window.presentationTools?.();break;case'presenter-video':window.presentationVideo?.();break;case'contents':contents();break;case'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('이 환경에서는 전체 화면이 지원되지 않아요. 브라우저 확대를 이용해 주세요.')}break;case'intro-toggle':state.introReveal=!state.introReveal;renderLesson();break;case'story-prev':state.steps=Math.max(0,state.steps-1);renderLesson();break;case'story-next':state.steps=(state.steps+1)%3;renderLesson();break;case'year':state.timeline[el.dataset.year]=!state.timeline[el.dataset.year];renderLesson();break;case'assemble':{if(matchMedia('(prefers-reduced-motion: reduce)').matches)break;const n=document.querySelector('.syllable');n?.animate([{transform:'scale(.6)',opacity:.2},{transform:'scale(1.1)',opacity:1},{transform:'scale(1)',opacity:1}],{duration:650,easing:'ease-out'});break}case'video-play':state.video=true;renderLesson();break;case'video-alternative':modal('영상 대신, 세 장면으로 생각해요',`<div class="alternative-grid">${[['writing-desk','뜻을 글로 전하려면 어떤 도움이 필요할까요?'],['hero-sejong','쉽게 배우고 쓰는 글자를 생각한 세종'],['classroom-note','오늘날 글자로 마음을 나누는 우리']].map(([f,t])=>`<article>${picture(f,t,'교육용 상상 삽화')}<h3>${t}</h3></article>`).join('')}</div><p class="prompt">세 장면을 잇는 공통된 마음은 무엇일까요?</p>`,true);break;case'activity-hint':state.showHint=!state.showHint;renderLesson();break;case'draft-reset':state.drafts={};renderLesson();break;case'card-preview':if(!state.drafts.message?.trim()){toast('전할 말을 고르거나 적어 주세요.');break}modal('내 마음 쪽지',`<div class="created-note"><small>${esc(state.drafts.recipient||'친구에게')}</small><h2>${esc(state.drafts.message)}</h2><span>한글로 전하는 다정한 마음</span></div><p class="prompt">누구에게, 어떤 마음을 전하는지 짝에게 이야기해요.</p>`);break;case'notice-preview':if(!state.drafts.rewrite?.trim()){toast('안내문을 먼저 고쳐 써 보세요.');break}modal('우리가 만든 쉬운 안내',`<div class="created-note"><small>${esc(state.drafts.audience||'우리 반 친구')}를 위한 안내</small><h2>${esc(state.drafts.rewrite)}</h2></div><p><strong>이렇게 바꾼 이유</strong><br>${esc(state.drafts.reason||'짝에게 말로 설명해 보세요.')}</p><div class="feedback">읽는 사람이 해야 할 일을 알 수 있나요? 익숙한 말인가요? 더 분명하게 쓸 부분을 서로 찾아보세요.</div>`);break;case'check-reveal':state.checkReveal=!state.checkReveal;renderLesson();break;case'summary-reveal':state.summary=Math.min(3,state.summary+1);renderLesson();break;case'quiz-start':state.quizStarted=true;state.quiz=0;renderLesson();break;case'quiz-restart':state.quizStarted=true;state.quizFinished=false;state.quiz=0;state.answers={};state.reveal={};renderLesson();break;case'quiz-hint':state.showHint=!state.showHint;renderLesson();break;case'quiz-reveal':state.reveal[getGrade().quiz[state.quiz].id]=true;renderLesson();break;case'quiz-next':if(!state.reveal[getGrade().quiz[state.quiz].id])return;if(state.quiz<getGrade().quiz.length-1)state.quiz++;else state.quizFinished=true;state.showHint=false;renderLesson();break;case'finish':state.reflection=true;renderLesson();break;case'pdf-student':window.open(`worksheets/hangul-${el.dataset.gradeId||state.grade}-student.pdf`,'_blank','noopener');break;case'qr':qrModal();break;case'qr-build':{let value=document.getElementById('share-base').value.trim();try{const u=new URL(value);if(!['https:','http:'].includes(u.protocol))throw Error();u.hash=`student/${state.grade}/5`;storage.set('share-base',value.split('#')[0]);makeQr(u.href,true)}catch{toast('올바른 수업 주소를 입력해 주세요.')}break}case'qr-video':makeQr(data.video.url,false);break;case'copy-link':try{await navigator.clipboard.writeText(el.dataset.url);toast('주소를 복사했어요.')}catch{toast('아래 주소를 길게 눌러 복사해 주세요.')}break;case'timer':toggleTimer();break;case'timer-reset':stopClock();seconds=getGrade().slides[state.index].minutes*60;renderLesson();break;}}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(el)handleAction(el)});
document.addEventListener('input',e=>{if(e.target.dataset.draft)state.drafts[e.target.dataset.draft]=e.target.value;if(e.target.dataset.answer)state.answers[e.target.dataset.answer]=e.target.value;});
document.addEventListener('change',e=>{if(e.target.dataset.draft)state.drafts[e.target.dataset.draft]=e.target.value;});
document.addEventListener('keydown',e=>{if(state.view!=='lesson'||document.querySelector('dialog[open]')||/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)||e.target.isContentEditable)return;if(['ArrowRight','PageDown'].includes(e.key)||(!state.student&&[' ','Enter'].includes(e.key)&&e.target.tagName!=='BUTTON'&&e.target.tagName!=='A')){e.preventDefault();moveSlide(1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();moveSlide(-1)}});
function route(){const m=location.hash.match(/^#(student|lesson)\/(1-2|3-4|5-6)\/(\d+)$/);if(m)startLesson(m[2],m[3],m[1]==='student');else if(!location.hash||location.hash==='#home')home()}
window.addEventListener('hashchange',route);route();
if(document.modelContext?.registerTool){const life=new AbortController();for(const tool of [{name:'read_hangeul_lesson',title:'한글날 수업 상태',description:'현재 학년과 장면을 확인합니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({view:state.view,grade:state.grade,slide:state.index+1,title:getGrade().slides[state.index].title})},{name:'open_hangeul_lesson',title:'한글날 수업 열기',description:'지정 학년의 수업 장면을 엽니다. 기존 활동 상태는 초기화됩니다.',inputSchema:{type:'object',properties:{grade:{type:'string',enum:['1-2','3-4','5-6']},slide:{type:'integer',minimum:1,maximum:10}},required:['grade','slide'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!data.grades[input.grade]||!Number.isInteger(input.slide)||input.slide<1||input.slide>10)throw new Error('학년과 1–10 장면을 확인해 주세요.');startLesson(input.grade,input.slide-1);return{grade:state.grade,slide:state.index+1,title:getGrade().slides[state.index].title}}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>life.abort(),{once:true})}
